public boolean isPowerOfThree(int n) {  
    // base case 
    if (n == 0)  
        return false;  

    // recursive case 
    if (n == 1)  
        return true;  

    // check remaining bits 
    int bit = n % 3;  
    return bit == 0 || isPowerOfThree(bit);  
